use vstd::prelude::*;

verus! {

/// Specification: multiplying a polynomial by `x` shifts coefficients right by 1,
/// inserting a leading 0. Here we model the result sequence.
spec fn polymulx_spec(c: Seq<f32>) -> Seq<f32> {
    seq![0.0f32] + c
}

fn polymulx(c: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result@ == polymulx_spec(c@),
{
    let n = c.len();
    let mut result: Vec<f32> = Vec::with_capacity(n + 1);

    // Prefix 0.0
    result.push(0.0);

    // Copy input left-to-right using an explicit counter.
    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            n == c.len(),
            // result is always: [0.0] followed by c[0..i)
            result@ == seq![0.0f32] + c@.subrange(0, i as int),
        decreases n - i,
    {
        result.push(c[i]);
        i += 1;
    }

    // At loop end, i == n, so result is [0.0] + c[0..n) == [0.0] + c
    assert(result@ == seq![0.0f32] + c@.subrange(0, n as int));
    assert(c@.subrange(0, n as int) == c@);
    assert(result@ == polymulx_spec(c@));

    result
}

} // verus!

